import { useRef, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "myelin" | "emerald" | "amber" | "rose";

const ACCENTS: readonly { id: Accent; label: string }[] = [
  { id: "myelin", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (accent: Accent) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const buttons = useRef<Array<HTMLButtonElement | null>>([]);
  const selectedIndex = Math.max(0, ACCENTS.findIndex((a) => a.id === value));

  function moveTo(index: number) {
    const wrapped = (index + ACCENTS.length) % ACCENTS.length;
    onChange(ACCENTS[wrapped].id);
    buttons.current[wrapped]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        event.preventDefault();
        moveTo(index + 1);
        break;
      case "ArrowLeft":
      case "ArrowUp":
        event.preventDefault();
        moveTo(index - 1);
        break;
      case "Home":
        event.preventDefault();
        moveTo(0);
        break;
      case "End":
        event.preventDefault();
        moveTo(ACCENTS.length - 1);
        break;
      default:
        break;
    }
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {ACCENTS.map((accent, index) => {
        const checked = accent.id === value;
        return (
          <button
            key={accent.id}
            ref={(el) => {
              buttons.current[index] = el;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={index === selectedIndex ? 0 : -1}
            data-accent={accent.id}
            className="accent-option"
            onClick={() => onChange(accent.id)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-swatch" aria-hidden="true" />
            <span className="accent-name">{accent.label}</span>
          </button>
        );
      })}
    </div>
  );
}
```

```css
.accent-picker {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(0.5rem, 1vw, 0.75rem);
}

.accent-option {
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  padding: 0.5em 0.9em;
  border: 1px solid var(--hair);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1.05rem);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.accent-option:hover {
  background: var(--myelin-wash);
}

.accent-option[aria-checked="true"] {
  border-color: var(--ink);
  background: var(--myelin-wash);
  font-weight: 600;
}

.accent-swatch {
  width: 1em;
  height: 1em;
  border-radius: 50%;
  flex: none;
}

.accent-option[data-accent="myelin"] .accent-swatch {
  background: var(--myelin);
}

.accent-option[data-accent="emerald"] .accent-swatch {
  background: var(--accent-emerald);
}

.accent-option[data-accent="amber"] .accent-swatch {
  background: var(--accent-amber);
}

.accent-option[data-accent="rose"] .accent-swatch {
  background: var(--accent-rose);
}

.accent-option[aria-checked="true"] .accent-swatch {
  box-shadow: 0 0 0 2px var(--slide), 0 0 0 3px var(--ink);
}

:root[data-motion="reduce"] .accent-option {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .accent-option {
    transition: none;
  }
}
```

The swatches use `--accent-emerald`, `--accent-amber` and `--accent-rose`, which are not in the token set. `--myelin` only shows the active accent, so the other three swatches have no token to draw from. Lint reports those three names as unknown. Add them to `styles.css` with each accent's day and night values from the token table, and the picker will render correctly in all eight combinations. I did not hard-code the hex values here.

